import { NextResponse } from 'next/server';
import { prisma } from '@/lib/db/prisma';

export async function GET(request: Request) {
  try {
    const { searchParams } = new URL(request.url);
    const merchantId = searchParams.get('merchantId');
    
    const products = await prisma.product.findMany({
      where: merchantId ? { merchantId } : undefined,
    });
    
    const transformedProducts = products.map(p => ({
      id: p.id,
      name: p.title,
      sku: p.sku,
      price: p.price,
      stock: p.stock,
      status: p.status === 'Active' ? 'active' : p.status === 'Draft' ? 'draft' : 'archived',
      category: p.category,
      image: p.image || ''
    }));

    return NextResponse.json(transformedProducts);
  } catch (error) {
    console.error('[Products API] Error:', error);
    return NextResponse.json({ error: 'Failed to fetch products' }, { status: 500 });
  }
}

export async function POST(request: Request) {
  try {
    const body = await request.json();
    
    const product = await prisma.product.create({
      data: {
        id: body.id || `PRD-${Date.now()}`,
        title: body.name,
        description: body.description || '',
        price: body.price,
        sku: body.sku,
        category: body.category || 'uncategorized',
        stock: body.stock || 0,
        sales: 0,
        status: body.status === 'active' ? 'Active' : body.status === 'draft' ? 'Draft' : 'Archived',
        image: body.image || '',
        merchantId: body.merchantId || 'merchant-001'
      }
    });

    const transformedProduct = {
      id: product.id,
      name: product.title,
      sku: product.sku,
      price: product.price,
      stock: product.stock,
      status: product.status === 'Active' ? 'active' : product.status === 'Draft' ? 'draft' : 'archived',
      category: product.category,
      image: product.image || ''
    };

    return NextResponse.json(transformedProduct);
  } catch (error) {
    console.error('[Products API] Error:', error);
    return NextResponse.json({ error: 'Failed to create product' }, { status: 500 });
  }
}

export async function PUT(request: Request) {
  try {
    const { searchParams } = new URL(request.url);
    const id = searchParams.get('id');
    
    if (!id) {
      return NextResponse.json({ error: 'Product ID is required' }, { status: 400 });
    }

    const body = await request.json();
    
    const updates: any = {};
    if (body.name) updates.title = body.name;
    if (body.price !== undefined) updates.price = body.price;
    if (body.stock !== undefined) updates.stock = body.stock;
    if (body.status) updates.status = body.status === 'active' ? 'Active' : body.status === 'draft' ? 'Draft' : 'Archived';
    if (body.category) updates.category = body.category;
    if (body.image) updates.image = body.image;
    if (body.sku) updates.sku = body.sku;

    const product = await prisma.product.update({
      where: { id },
      data: updates
    });

    const transformedProduct = {
      id: product.id,
      name: product.title,
      sku: product.sku,
      price: product.price,
      stock: product.stock,
      status: product.status === 'Active' ? 'active' : product.status === 'Draft' ? 'draft' : 'archived',
      category: product.category,
      image: product.image || ''
    };

    return NextResponse.json(transformedProduct);
  } catch (error) {
    console.error('[Products API] Error:', error);
    return NextResponse.json({ error: 'Failed to update product' }, { status: 500 });
  }
}

export async function DELETE(request: Request) {
  try {
    const { searchParams } = new URL(request.url);
    const id = searchParams.get('id');
    
    if (!id) {
      return NextResponse.json({ error: 'Product ID is required' }, { status: 400 });
    }

    await prisma.product.delete({
      where: { id }
    });

    return NextResponse.json({ success: true });
  } catch (error) {
    console.error('[Products API] Error:', error);
    return NextResponse.json({ error: 'Failed to delete product' }, { status: 500 });
  }
}
